export const thresholds = waveTables.flatMap(r=>r.wavesPower.flatMap((power,i)=>power>0?[{level:r.level,wave:i+1,power,verified:true,evidence:spiritSource.api,verifiedAt:spiritSource.checkedAt}]:[]));
export function verifiedThreshold(level, rows = thresholds, wave = 19) {
  const matches = rows.filter(r => r.level === level && (r.wave ?? 19) === wave);
  if (matches.length !== 1) return null;
  const r = matches[0];
  return r.verified === true && Number.isSafeInteger(r.power) && r.power >= 0
    && typeof r.evidence === 'string' && r.evidence.trim()
    && /^\d{4}-\d{2}-\d{2}$/.test(r.verifiedAt ?? '') ? r.power : null;
}
